def transform(grid):
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in ones)
    r1 = max(r for r, c in ones)
    c0 = min(c for r, c in ones)
    c1 = max(c for r, c in ones)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and not (r0 <= r <= r1 and c0 <= c <= c1)]
    if not outside:
        return panel

    er0 = min(r for r, c, v in outside)
    er1 = max(r for r, c, v in outside)
    ec0 = min(c for r, c, v in outside)
    ec1 = max(c for r, c, v in outside)

    def corner(r, c, top, bottom, left, right):
        return ("T" if abs(r - top) <= abs(r - bottom) else "B") + \
               ("L" if abs(c - left) <= abs(c - right) else "R")

    target = {v: corner(r, c, er0, er1, ec0, ec1) for r, c, v in outside}
    ph, pw = len(panel), len(panel[0])
    anchors = {}
    for r in range(ph):
        for c in range(pw):
            v = panel[r][c]
            if v in target:
                anchors[v] = (r, c)

    # Try the eight rotations/reflections and select the one that places
    # each internal anchor at the corner indicated by its outside counterpart.
    for flip in (False, True):
        for turns in range(4):
            a = [row[:] for row in panel]
            if flip:
                a = [row[::-1] for row in a]
            for _ in range(turns):
                a = [list(row) for row in zip(*a[::-1])]

            found = {}
            for r in range(len(a)):
                for c in range(len(a[0])):
                    if a[r][c] in target:
                        found[a[r][c]] = corner(
                            r, c, 0, len(a) - 1, 0, len(a[0]) - 1
                        )
            if all(found.get(v) == target[v] for v in anchors):
                return a

    return panel
